(1832690, 252341, 15711, '<td valign="top">Great title for this wonderful shot.  The yellows and complementary blues are gorgeous.  Those clouds - wow.  I love the sense of joy the jumping figure has.</td>', 'Great title for this wonderful shot.  The yellows and complementary blues are gorgeous.  Those clouds - wow.  I love the sense of joy the jumping figure has.', '2005-11-02 10:31:07.000000', NULL, 1),
(1832692, 251769, 15711, '<td valign="top">Aaah! Motion blur.  So pretty. I might straighten it out - it seems a tad tilted to the left. Great colors.  The leading line is good but if you straightened it, I think I''d like it better.</td>', 'Aaah! Motion blur.  So pretty. I might straighten it out - it seems a tad tilted to the left. Great colors.  The leading line is good but if you straightened it, I think I''d like it better.', '2005-11-02 10:31:55.000000', NULL, 1),
(1832695, 250151, 15711, '<td valign="top">I like the ghostly sense of this.  Kind of like something clandestine is going on. 7</td>', 'I like the ghostly sense of this.  Kind of like something clandestine is going on. 7', '2005-11-02 10:32:40.000000', NULL, 1),
