(1836638, 251170, 40019, '<td valign="top">Wow, love this picture!  The DOF, rich colors, stop action...outstanding!</td>', 'Wow, love this picture!  The DOF, rich colors, stop action...outstanding!', '2005-11-03 19:25:07.000000', NULL, 1),
