(1836960, 251707, 41574, '<td valign="top">Nice shot; I love the red tone. That said, I think the picture is just a little too under-exposed.</td>', 'Nice shot; I love the red tone. That said, I think the picture is just a little too under-exposed.', '2005-11-03 22:10:07.000000', NULL, 1),
(1836965, 252204, 34763, '<td valign="top">Biggest problem is steering wheel on wrong side ;)<br/></td>', 'Biggest problem is steering wheel on wrong side ;)', '2005-11-03 22:13:05.000000', NULL, 1),
(1836967, 252411, 41574, '<td valign="top">Not really a bad picture, but it feels, to me, as though the slow shutter-speed was used just for the sake of this challenge; that is, the speed selection doesn''t innately add to the photograph.</td>', 'Not really a bad picture, but it feels, to me, as though the slow shutter-speed was used just for the sake of this challenge; that is, the speed selection doesn''t innately add to the photograph.', '2005-11-03 22:13:29.000000', NULL, 1),
