(1849057, 251627, 20168, '<td valign="top">Great shot and lovely finish and it is not even a coastal scene! Congrats Zoomy!</td>', 'Great shot and lovely finish and it is not even a coastal scene! Congrats Zoomy!', '2005-11-09 00:22:44.000000', NULL, 0),
(1849068, 251473, 27735, '<td valign="top">I wish I could''ve shown the entire falls, but this is Vernal Falls in Yosemite National Park and the top of the falls is about 100 feet up in the sun!<br/> <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by srdanz:</b></div><hr/><i> Beautiful! One of better waterfalls/waterflows in the challenge. The composition is excellent. The only thing I may recommend is showing where the water comes from - the very top-right corner of the photo has the water falling from the sky and perhaps showing another ~50 pixels (in current resolution) would have been better. </i></td></tr></table></td>', 'I wish I could''ve shown the entire falls, but this is Vernal Falls in Yosemite National Park and the top of the falls is about 100 feet up in the sun! Originally posted by srdanz: Beautiful! One of better waterfalls/waterflows in the challenge. The composition is excellent. The only thing I may recommend is showing where the water comes from - the very top-right corner of the photo has the water falling from the sky and perhaps showing another ~50 pixels (in current resolution) would have been better. ', '2005-11-09 00:24:30.000000', NULL, 0),
(1849078, 251703, 37818, '<td valign="top">Ohh Man you were soo ripped off...I gave this shot a ten!</td>', 'Ohh Man you were soo ripped off...I gave this shot a ten!', '2005-11-09 00:25:31.000000', NULL, 0),
